node = {r[0]: r for r in rows}
def breadcrumb(i):
    vals=[]
    seen=set()
    while i:
        if i in seen: raise RuntimeError(f'cycle at {i}')
        seen.add(i)
        r=node[i]; vals.append(r[2]); i=r[3]
    return ' > '.join(reversed(vals))

def mapping(node_id, relation='direct_discipline', confidence='high'):
    r=node[node_id]
    return {
        'career_node_id': r[0],
        'career_node_slug': r[1],
        'career_breadcrumb': breadcrumb(node_id),
        'relation': relation,
        'confidence': confidence,
        'mapping_status': 'reviewed_with_career_tree_label_issue' if node_id == 20 else 'reviewed_against_local_tree'
    }

def one(i, rel='direct_discipline', conf='high'):
    return [mapping(i,rel,conf)]

